void union_sets(int a, int b) {
    int ra = find(a), rb = find(b);
    if (ra != rb) {
        if (size[ra] < size[rb]) {
            int temp = ra;
            ra = rb;
            rb = temp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }
}

