} Vec;

static void vec_push(Vec *vec, int x) {
    if (vec->size == vec->cap) {
        vec->cap = vec->cap ? vec->cap * 2 : 4;
        vec->data = (int*)realloc(vec->data, sizeof(int) * vec->cap);
    }
    vec->data[vec->size++] = x;
}

static int cmp_int(const void *a, const void *b) {
    int x = *(const int*)a;
    int y = *(const int*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static int lower_bound_int(int *arr, int n, int x) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (arr[m] < x) l = m + 1;
        else r = m;
    }
    return l;
}

/* Tarjan for biconnected components (vertex-based via edge stack) */
static int *disc, *low, *is_art;
static int timer_dfs;
static int *estack;
static int estack_sz;

static int **adj_to;
static int **adj_eid;
static int *adj_deg;

static int *edge_u, *edge_v;

static int *comp_cnt;
