static int *comp_sz;
static int comp_num, comp_cap;

static int *markv, mark_token;

static void add_component_from_stack_until(int stop_eid, int n) {
    if (comp_num == comp_cap) {
        comp_cap = comp_cap ? comp_cap * 2 : 8;
        comp_verts = (int**)realloc(comp_verts, sizeof(int*) * comp_cap);
        comp_sz = (int*)realloc(comp_sz, sizeof(int) * comp_cap);
    }

    Vec verts = {0};
    mark_token++;
    while (1) {
        int eid = estack[--estack_sz];
        int a = edge_u[eid], b = edge_v[eid];
        if (markv[a] != mark_token) {
            markv[a] = mark_token;
            vec_push(&verts, a);
        }
        if (markv[b] != mark_token) {
            markv[b] = mark_token;
            vec_push(&verts, b);
        }
        if (eid == stop_eid) break;
    }

    comp_sz[comp_num] = verts.size;
    comp_verts[comp_num] = verts.data;
    comp_num++;
}

static void dfs_bcc(int u, int peid, int n) {
    disc[u] = low[u] = ++timer_dfs;
    int child = 0;

    for (int i = 0; i < adj_deg[u]; i++) {
        int v = adj_to[u][i];
        int eid = adj_eid[u][i];
        if (eid == peid) continue;

        if (!disc[v]) {
            estack[estack_sz++] = eid;
            child++;
            dfs_bcc(v, eid, n);
            if (low[v] < low[u]) low[u] = low[v];

            if ((peid == -1 && child > 1) || (peid != -1 && low[v] >= disc[u])) {
                is_art[u] = 1;
            }
            if (low[v] >= disc[u]) {
                add_component_from_stack_until(eid, n);
            }
        } else if (disc[v] < disc[u]) {
            estack[estack_sz++] = eid;
            if (disc[v] < low[u]) low[u] = disc[v];
        }
    }
}

