    while (qh < qt) {
        int u = qarr[qh++];
        if (dist_arr[u] > dist_arr[best]) best = u;
        for (int i = 0; i < adj_deg[u]; i++) {
            int v = adj_to[u][i];
            if (!allowed[v]) continue;
            if (dist_arr[v] == -1) {
                dist_arr[v] = dist_arr[u] + 1;
                qarr[qt++] = v;
            }
        }
    }
    if (out_node) *out_node = best;
    return dist_arr[best];
}

