            for (int i = 0; i < bt_sz[u]; i++) {
                int v = bt[u][i];
                if (distw[v] == -1) {
                    distw[v] = distw[u] + weight[v];
                    parent[v] = u;
                    queue[qt++] = v;
                }
            }
        }

        for (int i = 0; i < nsz; i++) distw[nodes[i]] = -1, parent[nodes[i]] = -1;
