/*
Interpretation:
- Each string [a, b] is an undirected edge between distinct positive integers a and b.
- Connecting strings forms an undirected graph.
- A valid "chain" is a trail through connected strings such that each ring number
  (vertex) appears at most once in the chain, i.e. a simple path in the graph.
- Its length is the number of distinct integers on it = number of vertices in the path.

So the task is: given an undirected graph, find the maximum number of vertices
in any simple path among all connected components.

This is NP-hard in general, but the intended constraints for this classic problem
are small enough for DFS/backtracking. We compress vertex labels and run DFS from
every vertex, marking visited vertices, and maximize path length.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<pair<int,int>> edges;
    unordered_map<int,int> id;
    vector<int> vals;

    int a, b;
    while (cin >> a >> b) {
        edges.push_back({a, b});
        if (!id.count(a)) {
            id[a] = (int)id.size();
            vals.push_back(a);
        }
        if (!id.count(b)) {
            id[b] = (int)id.size();
            vals.push_back(b);
        }
    }

    int n = (int)id.size();
    if (n == 0) return 0;

    vector<vector<int>> g(n);
    for (auto &e : edges) {
        int u = id[e.first], v = id[e.second];
        if (u == v) continue;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    int ans = 1;
    vector<char> vis(n, 0);

    function<void(int,int)> dfs = [&](int u, int len) {
        ans = max(ans, len);
        for (int v : g[u]) {
            if (!vis[v]) {
                vis[v] = 1;
                dfs(v, len + 1);
                vis[v] = 0;
            }
        }
    };

    for (int s = 0; s < n; ++s) {
        fill(vis.begin(), vis.end(), 0);
        vis[s] = 1;
        dfs(s, 1);
    }

    cout << ans << '\n';
    return 0;
}

