from collections import defaultdict, deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    adj = defaultdict(list)
    for _ in range(n):
        a = int(next(it))
        b = int(next(it))
        adj[a].append(b)
        adj[b].append(a)

    visited = set()
    max_len = 0

    for start in adj:
        if start in visited:
            continue
        # BFS to find farthest node and mark visited
        q = deque([start])
        visited.add(start)
        far_node = start
        dist = {start: 0}
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    dist[v] = dist[u] + 1
                    if dist[v] > dist[far_node]:
                        far_node = v
                    q.append(v)
        # Now BFS from far_node to get max distance in this component
        q = deque([far_node])
        dist2 = {far_node: 0}
        visited2 = {far_node}
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in visited2:
                    visited2.add(v)
                    dist2[v] = dist2[u] + 1
                    q.append(v)
        diameter = max(dist2.values())
        if diameter + 1 > max_len:
            max_len = diameter + 1

    print(max_len)

