        int child = 0;

        for (int v : g[u]) {
            if (disc[v] == 0) {
                child++;
                addEdgeToStack(u, v);
                dfsBCC(v, u);
                low[u] = Math.min(low[u], low[v]);

                if ((parent == -1 && child > 1) || (parent != -1 && low[v] >= disc[u])) {
                    isArticulation[u] = true;
                }
                if (low[v] >= disc[u]) {
                    popBlock(u, v);
                }
            } else if (v != parent && disc[v] < disc[u]) {
                addEdgeToStack(u, v);
                low[u] = Math.min(low[u], disc[v]);
            }
        }
    }

    static ArrayList<Integer>[] tree;
    static boolean[] isBlockNode;
    static int totalNodes;

    static int bfsFarthest(int src) {
        int[] dist = new int[totalNodes];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(src);
        dist[src] = isBlockNode[src] ? 1 : 0;

        int best = src;
        while (!q.isEmpty()) {
            int u = q.poll();
            if (dist[u] > dist[best]) best = u;
            for (int v : tree[u]) {
                int w = isBlockNode[v] ? 1 : 0;
                if (dist[v] == -1) {
                    dist[v] = dist[u] + w;
                    q.add(v);
                }
            }
        }
        return best;
    }

    static int bfsDiameterFrom(int src) {
        int[] dist = new int[totalNodes];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(src);
        dist[src] = isBlockNode[src] ? 1 : 0;

        int ans = dist[src];
        while (!q.isEmpty()) {
            int u = q.poll();
            ans = Math.max(ans, dist[u]);
            for (int v : tree[u]) {
                int w = isBlockNode[v] ? 1 : 0;
                if (dist[v] == -1) {
                    dist[v] = dist[u] + w;
                    q.add(v);
                }
            }
        }
        return ans;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        n = fs.nextInt();

        HashMap<Integer, Integer> compress = new HashMap<>();
        int[] a = new int[n];
        int[] b = new int[n];
        int idCnt = 0;

        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
            b[i] = fs.nextInt();
            if (!compress.containsKey(a[i])) compress.put(a[i], idCnt++);
            if (!compress.containsKey(b[i])) compress.put(b[i], idCnt++);
        }

        int m = idCnt;
        g = new ArrayList[m];
        for (int i = 0; i < m; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            int u = compress.get(a[i]);
            int v = compress.get(b[i]);
            g[u].add(v);
            g[v].add(u);
        }

        disc = new int[m];
        low = new int[m];
        isArticulation = new boolean[m];
        stack = new int[2 * n + 5];

        for (int i = 0; i < m; i++) {
            if (disc[i] == 0 && !g[i].isEmpty()) {
                dfsBCC(i, -1);
                if (top > 0) {
                    HashSet<Integer> set = new HashSet<>();
                    while (top > 0) {
                        int bb = stack[--top];
                        int aa = stack[--top];
                        set.add(aa);
                        set.add(bb);
                    }
                    int[] arr = new int[set.size()];
                    int idx = 0;
                    for (int x : set) arr[idx++] = x;
                    blocks.add(arr);
                }
            }
        }

        int artCount = 0;
        int[] artId = new int[m];
        Arrays.fill(artId, -1);
        for (int i = 0; i < m; i++) {
            if (isArticulation[i]) artId[i] = artCount++;
        }

        int blockCount = blocks.size();
        totalNodes = artCount + blockCount;
        tree = new ArrayList[totalNodes];
        isBlockNode = new boolean[totalNodes];
        for (int i = 0; i < totalNodes; i++) tree[i] = new ArrayList<>();

        for (int i = 0; i < blockCount; i++) {
            int nodeId = artCount + i;
            isBlockNode[nodeId] = true;
            for (int v : blocks.get(i)) {
                if (isArticulation[v]) {
                    int aid = artId[v];
                    tree[nodeId].add(aid);
                    tree[aid].add(nodeId);
                }
            }
        }

        boolean[] vis = new boolean[totalNodes];
        int answer = 0;

        for (int i = 0; i < totalNodes; i++) {
            if (!vis[i]) {
                ArrayDeque<Integer> q = new ArrayDeque<>();
                q.add(i);
                vis[i] = true;
                ArrayList<Integer> comp = new ArrayList<>();
                comp.add(i);
                while (!q.isEmpty()) {
                    int u = q.poll();
                    for (int v : tree[u]) {
                        if (!vis[v]) {
                            vis[v] = true;
                            q.add(v);
                            comp.add(v);
                        }
                    }
                }

                int start = comp.get(0);
                int far = bfsFarthest(start);
                int diam = bfsDiameterFrom(far);
                answer = Math.max(answer, diam);
            }
        }

        // Special case: if there are edges but no articulation points and exactly one block component,
        // answer already equals number of vertices in that block.
        // Also if graph contains isolated vertices only, problem guarantees at least one chain from strings.

        System.out.println(answer);
    }
